/**
 * @param mixed $lookupValue
 * @param mixed $lookupArray
 * @param mixed $indexNumber
 * @param mixed $notExactMatch
 *
 * @return mixed
 */
private function performVerticalLookup($lookupValue, $lookupArray, $indexNumber, $notExactMatch)
{
    $this->lookupValue = $lookupValue;
    $this->lookupArray = is_array($lookupArray) ? $lookupArray : [];
    $this->indexNumber = $indexNumber;
    $this->notExactMatch = (bool) ($notExactMatch ?? true);
    $this->matchedRow = null;

    try {
        self::validateLookupArray($lookupArray);
        $this->lookupArray = $lookupArray;
        $this->indexNumber = self::validateIndexLookup($this->lookupArray, $this->indexNumber);
    } catch (Exception $e) {
        return $e->getMessage();
    }

    $f = array_keys($this->lookupArray);
    $firstRow = array_pop($f);
    if ((!is_array($this->lookupArray[$firstRow])) || ($this->indexNumber > count($this->lookupArray[$firstRow]))) {
        return ExcelError::REF();
    }
    $columnKeys = array_keys($this->lookupArray[$firstRow]);
    $returnColumn = $columnKeys[--$this->indexNumber];
    $this->firstColumn = array_shift($columnKeys) ?? 1;

    if (!$this->notExactMatch) {
        $callable = [$this, 'sortLookupRows'];
        uasort($this->lookupArray, $callable);
    }

    $this->matchedRow = $this->searchVertical($this->lookupValue, $this->lookupArray, $this->firstColumn, $this->notExactMatch);

    if ($this->matchedRow !== null) {
        return $this->lookupArray[$this->matchedRow][$returnColumn];
    }

    return ExcelError::NA();
}

/**
