private function performHorizontalLookup($lookupValue, $lookupArray, $indexNumber, $notExactMatch)
{
    $this->lookupValue = $lookupValue;
    $this->lookupArray = is_array($lookupArray) ? $lookupArray : [];
    $this->indexNumber = $indexNumber;
    $this->notExactMatch = (bool) ($notExactMatch ?? true);
    $this->matchedRow = null;

    try {
        self::validateLookupArray($lookupArray);
        $this->lookupArray = $this->convertLiteralLookupArray($lookupArray);
        $this->indexNumber = self::validateIndexLookup($this->lookupArray, $this->indexNumber);
    } catch (Exception $e) {
        return $e->getMessage();
    }

    $f = array_keys($this->lookupArray);
    $firstRow = reset($f);
    if ((!is_array($this->lookupArray[$firstRow])) || ($this->indexNumber > count($this->lookupArray))) {
        return ExcelError::REF();
    }

    $firstkey = $f[0] - 1;
    $returnColumn = $firstkey + $this->indexNumber;
    $this->firstColumn = array_shift($f) ?? 1;
    $this->matchedRow = $this->searchHorizontal($this->lookupValue, $this->lookupArray, $this->firstColumn, $this->notExactMatch);

    if ($this->matchedRow !== null) {
        return $this->lookupArray[$returnColumn][Coordinate::stringFromColumnIndex($this->matchedRow)];
    }

    return ExcelError::NA();
}

private function sortLookupRows(array $a, array $b): int
{
    reset($a);
    $this->firstColumn = key($a);
    $aLower = StringHelper::strToLower((string) $a[$this->firstColumn]);
    $bLower = StringHelper::strToLower((string) $b[$this->firstColumn]);

    if ($aLower == $bLower) {
        return 0;
    }

    return ($aLower < $bLower) ? -1 : 1;
}

/**
 * @param mixed $lookupValue
 * @param int|string $column
 */
private function searchVertical($lookupValue, array $lookupArray, $column, bool $notExactMatch): ?int
{
    $this->lookupValue = $lookupValue;
    $this->lookupArray = $lookupArray;
    $this->firstColumn = $column;
    $this->notExactMatch = $notExactMatch;
    $this->normalizedLookup = StringHelper::strToLower((string) $this->lookupValue);
    $this->matchedRow = null;

    foreach ($this->lookupArray as $rowKey => $rowData) {
        $bothNumeric = is_numeric($this->lookupValue) && is_numeric($rowData[$this->firstColumn]);
        $bothNotNumeric = !is_numeric($this->lookupValue) && !is_numeric($rowData[$this->firstColumn]);
        $cellDataLower = StringHelper::strToLower((string) $rowData[$this->firstColumn]);

